#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Hertz),
        Frequency::from_hertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Hertz),
        Frequency::from_base(v).as_hertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Microhertz),
        Frequency::from_microhertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Microhertz),
        Frequency::from_base(v).as_microhertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Millihertz),
        Frequency::from_millihertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Millihertz),
        Frequency::from_base(v).as_millihertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Kilohertz),
        Frequency::from_kilohertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Kilohertz),
        Frequency::from_base(v).as_kilohertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Megahertz),
        Frequency::from_megahertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Megahertz),
        Frequency::from_base(v).as_megahertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Gigahertz),
        Frequency::from_gigahertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Gigahertz),
        Frequency::from_base(v).as_gigahertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::Terahertz),
        Frequency::from_terahertz(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::Terahertz),
        Frequency::from_base(v).as_terahertz()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::RadianPerSecond),
        Frequency::from_radians_per_second(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::RadianPerSecond),
        Frequency::from_base(v).as_radians_per_second()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::CyclePerMinute),
        Frequency::from_cycles_per_minute(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::CyclePerMinute),
        Frequency::from_base(v).as_cycles_per_minute()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::CyclePerHour),
        Frequency::from_cycles_per_hour(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::CyclePerHour),
        Frequency::from_base(v).as_cycles_per_hour()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::BeatPerMinute),
        Frequency::from_beats_per_minute(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::BeatPerMinute),
        Frequency::from_base(v).as_beats_per_minute()
    );
    assert_eq!(
        Frequency::new(v, FrequencyUnit::PerSecond),
        Frequency::from_per_second(v)
    );
    assert_eq!(
        Frequency::from_base(v).convert_to(FrequencyUnit::PerSecond),
        Frequency::from_base(v).as_per_second()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Frequency::from_base(v);
        let auto = q.auto_unit();
        assert_close(Frequency::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in FrequencyUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Frequency::from_base(0.0).auto_unit().unit,
        FrequencyUnit::Hertz
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("Hz".parse::<FrequencyUnit>(), Ok(FrequencyUnit::Hertz));
    assert_eq!(
        format!("2.5 {}", "Hz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Hertz))
    );
    assert_eq!(
        "µHz".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::Microhertz)
    );
    assert_eq!(
        format!("2.5 {}", "µHz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Microhertz))
    );
    assert_eq!(
        "mHz".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::Millihertz)
    );
    assert_eq!(
        format!("2.5 {}", "mHz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Millihertz))
    );
    assert_eq!("kHz".parse::<FrequencyUnit>(), Ok(FrequencyUnit::Kilohertz));
    assert_eq!(
        format!("2.5 {}", "kHz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Kilohertz))
    );
    assert_eq!("MHz".parse::<FrequencyUnit>(), Ok(FrequencyUnit::Megahertz));
    assert_eq!(
        format!("2.5 {}", "MHz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Megahertz))
    );
    assert_eq!("GHz".parse::<FrequencyUnit>(), Ok(FrequencyUnit::Gigahertz));
    assert_eq!(
        format!("2.5 {}", "GHz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Gigahertz))
    );
    assert_eq!("THz".parse::<FrequencyUnit>(), Ok(FrequencyUnit::Terahertz));
    assert_eq!(
        format!("2.5 {}", "THz").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::Terahertz))
    );
    assert_eq!(
        "rad/s".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::RadianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "rad/s").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::RadianPerSecond))
    );
    assert_eq!(
        "cpm".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::CyclePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "cpm").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::CyclePerMinute))
    );
    assert_eq!(
        "cph".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::CyclePerHour)
    );
    assert_eq!(
        format!("2.5 {}", "cph").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::CyclePerHour))
    );
    assert_eq!(
        "bpm".parse::<FrequencyUnit>(),
        Ok(FrequencyUnit::BeatPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "bpm").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::BeatPerMinute))
    );
    assert_eq!("s⁻¹".parse::<FrequencyUnit>(), Ok(FrequencyUnit::PerSecond));
    assert_eq!(
        format!("2.5 {}", "s⁻¹").parse::<Frequency>(),
        Ok(Frequency::new(2.5, FrequencyUnit::PerSecond))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Frequency>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Frequency::from_base(6.0);
    let b = Frequency::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Frequency::<i64>::from_base(7);
    let b = Frequency::<i64>::from_base(2);
    assert_eq!(a + b, Frequency::from_base(9));
    assert_eq!(a % b, Frequency::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<Frequency<i64>>(),
        Frequency::from_base(9)
    );
}
